operation.add:
{% if shippingdata_plus_own_column %}
<td class="text-left sdp-cn" style="white-space: nowrap;" data-order-id="{{ order.order_id }}"></td>
{% endif %}

{% if shippingdata_plus_list %}
<script type="text/javascript"><!--
(function() {
  var copyTitle = '{{ shippingdata_plus_copy|e('js') }}';
  var trackTitle = '{{ shippingdata_plus_track|e('js') }}';
  var ownColumn = {{ shippingdata_plus_own_column ? 'true' : 'false' }};

  function shippingdataPlusCopy(text, button) {
    var done = function() {
      var icon = $(button).find('i');
      icon.removeClass('fa-clipboard').addClass('fa-check text-success');
      var timer = $(button).data('sdpTimer');
      if (timer) {
        clearTimeout(timer);
      }
      $(button).data('sdpTimer', setTimeout(function() {
        icon.removeClass('fa-check text-success').addClass('fa-clipboard');
      }, 2000));
    };
    var fallback = function() {
      var area = document.createElement('textarea');
      area.value = text;
      area.setAttribute('readonly', 'readonly');
      area.style.position = 'absolute';
      area.style.left = '-9999px';
      document.body.appendChild(area);
      area.select();
      var ok = false;
      try {
        ok = document.execCommand('copy');
      } catch (err) {
        ok = false;
      }
      document.body.removeChild(area);
      if (ok) {
        done();
      }
    };
    if (navigator.clipboard && window.isSecureContext) {
      navigator.clipboard.writeText(text).then(done).catch(fallback);
    } else {
      fallback();
    }
  }

  function shippingdataPlusLink(url) {
    return /^https:\/\/(novaposhta\.ua|track\.ukrposhta\.ua|rozetka\.delivery|ua\.meest\.com)\//.test(url);
  }

  function shippingdataPlusHex(value) {
    return /^#[0-9A-Fa-f]{6}$/.test(String(value || '')) ? String(value) : '';
  }

  function shippingdataPlusTrack(row) {
    if (!row || !shippingdataPlusLink(row.tracking)) {
      return null;
    }
    var bg = shippingdataPlusHex(row.bg);
    var ink = shippingdataPlusHex(row.ink);
    var link = $('<a class="btn btn-xs" target="_blank" rel="noopener noreferrer" style="margin-left:4px;">');
    link.attr('href', row.tracking);
    link.attr('data-toggle', 'tooltip');
    link.attr('title', trackTitle);
    if (bg && ink) {
      link.css({ backgroundColor: bg, borderColor: bg, color: ink });
    }
    link.html('<i class="fa fa-external-link"></i>');
    return link;
  }

  function shippingdataPlusFill(cell, row) {
    if (!cell || !cell.length || !row || !row.number) {
      return;
    }
    var shown = row.display ? String(row.display) : String(row.number);
    cell.append($('<span style="white-space:nowrap;">').text(shown));
    var copy = $('<button type="button" class="btn btn-default btn-xs" style="margin-left:4px;">').attr('data-toggle', 'tooltip').attr('title', copyTitle).html('<i class="fa fa-clipboard"></i>');
    copy.on('click', function(e) {
      e.preventDefault();
      shippingdataPlusCopy(String(row.number), this);
    });
    cell.append(copy);
    copy.tooltip({container: 'body'});
    var track = shippingdataPlusTrack(row);
    if (track) {
      cell.append(track);
    }
  }

  function shippingdataPlusRow(id) {
    var found = $();
    $('#form-order input[name="selected[]"]').each(function() {
      if (String($(this).val()) === String(id)) {
        found = $(this).closest('tr');
        return false;
      }
    });
    return found;
  }

  if (ownColumn) {
    $('#form-order td[colspan]').each(function() {
      var span = parseInt($(this).attr('colspan'), 10);

      if (!isNaN(span)) {
        $(this).attr('colspan', span + 1);
      }
    });
  }

  var ids = [];
  if (ownColumn) {
    $('.sdp-cn').each(function() {
      ids.push($(this).attr('data-order-id'));
    });
  } else {
    $('#form-order input[name="selected[]"]').each(function() {
      ids.push($(this).val());
    });
  }
  if (!ids.length) {
    return;
  }
  $.ajax({
    url: 'index.php?route=extension/module/shippingdata_plus/orders&user_token={{ user_token|e('js') }}',
    type: 'POST',
    data: { order_id: ids },
    dataType: 'json',
    success: function(json) {
      if (!json || !json.orders) {
        return;
      }
      $.each(json.orders, function(id, row) {
        if (!/^[0-9]+$/.test(String(id))) {
          return;
        }
        if (ownColumn) {
          shippingdataPlusFill($('.sdp-cn').filter(function() {
            return String($(this).attr('data-order-id')) === String(id);
          }), row);
          return;
        }
        var rowEl = shippingdataPlusRow(id);
        var cell = rowEl.find('td.npp-ol-cell').first();
        if (!cell.length || cell.find('.npp-ol').length) {
          return;
        }
        shippingdataPlusFill(cell, row);
      });
    }
  });
})();
//--></script>
{% endif %}

{% if shippingdata_plus %}
<div id="sdp-order-info" class="hidden"> <span style="display:inline-flex;align-items:center;line-height:1;white-space:nowrap;">{{ shippingdata_plus.display|e }} <button type="button" class="btn btn-default btn-xs sdp-copy" data-number="{{ shippingdata_plus.number|e('html_attr') }}" data-toggle="tooltip" title="{{ shippingdata_plus_copy|e('html_attr') }}" style="margin-left:4px;"><i class="fa fa-clipboard"></i></button> {% if shippingdata_plus.tracking %}<a class="btn btn-xs" href="{{ shippingdata_plus.tracking|e('html_attr') }}" target="_blank" rel="noopener noreferrer" data-toggle="tooltip" title="{{ shippingdata_plus_track|e('html_attr') }}" style="margin-left:4px;background-color:{{ shippingdata_plus.bg|e('html_attr') }};border-color:{{ shippingdata_plus.bg|e('html_attr') }};color:{{ shippingdata_plus.ink|e('html_attr') }};"><i class="fa fa-external-link"></i></a>{% endif %}</span></div>
<script type="text/javascript"><!--
(function() {
  var box = document.getElementById('sdp-order-info');
  var button = document.getElementById('sdp-shipping-method');
  var cell = button && button.parentNode ? button.parentNode.nextElementSibling : null;
  if (box && cell) {
    while (box.firstChild) {
      cell.appendChild(box.firstChild);
    }
    cell.style.display = 'flex';
    cell.style.alignItems = 'center';
    cell.style.justifyContent = 'space-between';
    cell.style.gap = '8px';
    if (box.parentNode) {
      box.parentNode.removeChild(box);
    }
    if (window.jQuery) {
      jQuery(cell).find('.sdp-copy').tooltip({container: 'body'});
    }
  }
  function done(target) {
    var icon = target.querySelector('i');
    if (!icon) {
      return;
    }
    icon.className = 'fa fa-check text-success';
    if (target.sdpTimer) {
      clearTimeout(target.sdpTimer);
    }
    target.sdpTimer = setTimeout(function() {
      icon.className = 'fa fa-clipboard';
    }, 2000);
  }
  var copies = cell ? cell.querySelectorAll('.sdp-copy') : [];
  for (var i = 0; i < copies.length; i++) {
    copies[i].addEventListener('click', function() {
      var text = this.getAttribute('data-number');
      var target = this;
      var fallback = function() {
        var area = document.createElement('textarea');
        area.value = text;
        area.setAttribute('readonly', 'readonly');
        area.style.position = 'absolute';
        area.style.left = '-9999px';
        document.body.appendChild(area);
        area.select();
        var ok = false;
        try {
          ok = document.execCommand('copy');
        } catch (err) {
          ok = false;
        }
        document.body.removeChild(area);
        if (ok) {
          done(target);
        }
      };
      if (navigator.clipboard && window.isSecureContext) {
        navigator.clipboard.writeText(text).then(function() { done(target); }).catch(fallback);
      } else {
        fallback();
      }
    });
  }
})();
//--></script>
{% endif %}

if ($this->config->get('module_shippingdata_plus_status') && $this->config->get('module_shippingdata_plus_account')) {
	require_once(dirname(DIR_APPLICATION) . '/admin/model/extension/module/shippingdata_plus.php');

	$shippingdata_plus_model = new ModelExtensionModuleShippingdataPlus($this->registry);
	$shippingdata_plus_ids = array();

	foreach ($data['orders'] as $shippingdata_plus_order) {
		$shippingdata_plus_ids[] = $shippingdata_plus_order['order_id'];
	}

	$shippingdata_plus_map = $shippingdata_plus_model->getOrdersTtn($shippingdata_plus_ids);

	foreach ($data['orders'] as $shippingdata_plus_key => $shippingdata_plus_order) {
		$shippingdata_plus_id = (string)(int)$shippingdata_plus_order['order_id'];

		if (isset($shippingdata_plus_map[$shippingdata_plus_id])) {
			$data['orders'][$shippingdata_plus_key]['shippingdata_plus'] = $shippingdata_plus_map[$shippingdata_plus_id];
		}
	}

	$data['shippingdata_plus_account'] = !$shippingdata_plus_model->proAccountColumn();
	$data['shippingdata_plus_text_shipment'] = $shippingdata_plus_model->phrase('text_shipment');
	$data['shippingdata_plus_text_track'] = $shippingdata_plus_model->phrase('text_track');
}

{% if shippingdata_plus_account %}
<td class="text-left">{% if order.shippingdata_plus %}<span style="white-space:nowrap;">{{ order.shippingdata_plus.carrier_name|e }} {{ order.shippingdata_plus.display|e }}{% if order.shippingdata_plus.tracking %} <a class="btn btn-xs sdp-btn-xs" href="{{ order.shippingdata_plus.tracking|e('html_attr') }}" target="_blank" rel="noopener noreferrer" data-toggle="tooltip" title="{{ shippingdata_plus_text_track|e('html_attr') }}" style="margin-left:4px;background-color:{{ order.shippingdata_plus.bg|e('html_attr') }};border-color:{{ order.shippingdata_plus.bg|e('html_attr') }};color:{{ order.shippingdata_plus.ink|e('html_attr') }};"><i class="fa fa-external-link"></i></a>{% endif %}</span>{% endif %}</td>
{% endif %}

if (!empty($data['logged']) && $this->config->get('module_shippingdata_plus_status') && $this->config->get('module_shippingdata_plus_navbar')) {
	$this->load->language('extension/module/shippingdata_plus');
	$this->load->model('extension/module/shippingdata_plus');

	$data['shippingdata_plus_show'] = true;
	$data['shippingdata_plus_text_check'] = $this->language->get('text_check');
	$data['shippingdata_plus_text_cities'] = $this->language->get('text_cities');
	$data['shippingdata_plus_text_departments'] = $this->language->get('text_departments');
	$data['shippingdata_plus_text_settings'] = $this->language->get('text_settings');
	$data['shippingdata_plus_text_menu'] = $this->language->get('text_menu');
	$data['shippingdata_plus_button_check'] = $this->language->get('button_check');
	$data['shippingdata_plus_button_refresh'] = $this->language->get('button_refresh');
	$data['shippingdata_plus_text_ping'] = $this->language->get('text_ping');
	$data['shippingdata_plus_text_go_settings'] = $this->language->get('text_go_settings');
	$data['shippingdata_plus_success_ping'] = $this->language->get('success_ping');
	$data['shippingdata_plus_success_update'] = $this->language->get('success_update');
	$data['shippingdata_plus_settings'] = $this->url->link('extension/module/shippingdata_plus', 'user_token=' . $this->session->data['user_token'], true);
	$data['shippingdata_plus_token'] = $this->session->data['user_token'];
	$data['shippingdata_plus_carriers'] = array();

	foreach ($this->model_extension_module_shippingdata_plus->carrierCodes() as $shippingdata_plus_code) {
		if (!$this->config->get('shipping_' . $shippingdata_plus_code . '_status')) {
			continue;
		}

		$this->load->language('extension/shipping/' . $shippingdata_plus_code);

		$data['shippingdata_plus_carriers'][] = array(
			'code'        => $shippingdata_plus_code,
			'name'        => $this->language->get('heading_title'),
			'href'        => $this->url->link('extension/shipping/' . $shippingdata_plus_code, 'user_token=' . $this->session->data['user_token'], true),
			'cities'      => $this->model_extension_module_shippingdata_plus->countType($shippingdata_plus_code, 'cities'),
			'departments' => $this->model_extension_module_shippingdata_plus->countType($shippingdata_plus_code, 'departments')
		);
	}

	$this->load->language('common/header');
}

{% if shippingdata_plus_show %}
<style>
.sdp-menu { min-width: 320px; }
.sdp-menu > li > .sdp-row { margin-left: 0; margin-right: 0; padding: 3px 15px; }
.sdp-menu > li > .sdp-row > [class*="col-"] { padding: 2px 4px; }
.sdp-menu > li > .sdp-row > .col-xs-2 { text-align: right; white-space: nowrap; }
.sdp-menu > li > .sdp-row > .col-xs-5 + .col-xs-5 { white-space: normal; word-wrap: break-word; }
.sdp-menu > li.dropdown-header > a.btn { display: inline-block; float: none; clear: none; margin-left: 6px; padding: 1px 5px; line-height: 1.5; vertical-align: middle; }
</style>
<script type="text/javascript"><!--
var sdpTextPing = '{{ shippingdata_plus_text_ping|e('js') }}';
var sdpSuccessPing = '{{ shippingdata_plus_success_ping|e('js') }}';
var sdpSuccessUpdate = '{{ shippingdata_plus_success_update|e('js') }}';

function sdpFormat(text, a, b) {
  var out = String(text).replace('%s', a);

  if (arguments.length > 2) {
    out = out.replace('%s', b);
  }

  return out;
}

function sdpCarrierName(code) {
  var name = $('#sdp-head-' + code).attr('data-name');

  return name ? name : code;
}

function sdpAlert(kind, message) {
  var $box = $('<div class="alert alert-dismissible">').addClass(kind === 'success' ? 'alert-success' : 'alert-danger');

  $box.append($('<i class="fa">').addClass(kind === 'success' ? 'fa-check-circle' : 'fa-exclamation-circle'));
  $box.append(document.createTextNode(' ' + message + ' '));
  $box.append('<button type="button" class="close" data-dismiss="alert">&times;</button>');

  var $host = $('#content > .container-fluid');

  if (!$host.length) {
    $host = $('#content');
  }

  if (!$host.length) {
    $host = $('body');
  }

  $host.first().prepend($box);
}

function sdpPing(code) {
  var $label = $('#sdp-ping-' + code);
  var $btn = $('#sdp-ping-btn-' + code);
  var $icon = $btn.children('i');
  if ($btn.prop('disabled')) {
    return;
  }
  $.ajax({
    url: 'index.php?route=extension/module/shippingdata_plus/ping&user_token={{ shippingdata_plus_token|e('js') }}&carrier=' + encodeURIComponent(code),
    dataType: 'json',
    beforeSend: function() {
      $btn.prop('disabled', true);
      $icon.attr('data-sdp-icon', $icon.attr('class')).attr('class', 'fa fa-spinner fa-spin');
    },
    complete: function() {
      $btn.prop('disabled', false);
      $icon.attr('class', $icon.attr('data-sdp-icon') || 'fa fa-plug');
    },
    success: function(json) {
      $label.removeClass('text-success text-warning text-danger');
      if (!json) {
        return;
      }
      if (json.color === 'success' || json.color === 'warning' || json.color === 'danger') {
        $label.addClass('text-' + json.color);
      }
      if (json.ok) {
        $label.text(sdpFormat(sdpTextPing, json.ms));
        sdpAlert('success', sdpFormat(sdpSuccessPing, sdpCarrierName(code), json.ms));
      } else {
        $label.addClass('text-danger').text(json.error || '');
        sdpAlert('danger', json.error || '');
      }
    }
  });
}
function sdpUpdate(code, type) {
  var $btn = $('#sdp-refresh-' + code + '-' + type);
  var $icon = $btn.children('i');
  if ($btn.prop('disabled')) {
    return;
  }
  $.ajax({
    url: 'index.php?route=extension/module/shippingdata_plus/update&user_token={{ shippingdata_plus_token|e('js') }}&carrier=' + encodeURIComponent(code) + '&type=' + encodeURIComponent(type),
    dataType: 'json',
    timeout: 0,
    beforeSend: function() {
      $btn.prop('disabled', true);
      $icon.attr('data-sdp-icon', $icon.attr('class')).attr('class', 'fa fa-spinner fa-spin');
    },
    complete: function() {
      $btn.prop('disabled', false);
      $icon.attr('class', $icon.attr('data-sdp-icon') || 'fa fa-refresh');
    },
    success: function(json) {
      var $delta = $('#sdp-delta-' + code + '-' + type);
      $delta.removeClass('text-danger');
      if (!json) {
        return;
      }
      if (json.error && typeof json.count === 'undefined') {
        $delta.addClass('text-danger').text(json.error);
        sdpAlert('danger', json.error);
        return;
      }
      if (typeof json.count !== 'undefined') {
        $('#sdp-count-' + code + '-' + type).text(json.count);
      }
      if (json.error) {
        $delta.addClass('text-danger').text(json.error);
        sdpAlert('danger', json.error);
        return;
      }
      var delta = parseInt(json.delta, 10);
      if (isNaN(delta)) {
        delta = 0;
      }
      var signed = delta > 0 ? '+' + delta : String(delta);
      $delta.text(signed);
      sdpAlert('success', sdpFormat(sdpSuccessUpdate, sdpCarrierName(code), signed));
    }
  });
}
$(document).ready(function() {
  $('#sdp-truck-toggle').tooltip({container: 'body'});
  $('.sdp-menu [data-toggle="tooltip"]').tooltip({container: 'body'});
});
//--></script>
{% endif %}
